css:
/* Meridian — a dark editorial OS. Deep ink, warm ivory, brass rules. */
:root, .shell {
  --ground-radius: 2px;
  --window-radius: 3px;
  --window-content-radius: 0 0 3px 3px;
  --window-control-radius: 2px;
  --dock-radius: 2px;
  --dock-item-radius: 2px;
  --group-radius: 3px;
  --toolbar-radius: 2px;
  --command-palette-radius: 3px;
  --menu-radius: 3px;
  --menu-item-radius: 2px;
  --menu-background: var(--rumahl-ui-color-panel-background);
  --menu-border: 1px solid var(--rumahl-ui-color-outline);
  --menu-shadow: 0 24px 56px rgb(0 0 0 / 0.55);
  --menu-backdrop: none;
  --menu-item-hover: color-mix(in srgb, var(--rumahl-ui-color-accent) 14%, transparent);
  --widget-background: var(--rumahl-ui-color-surface);
  --widget-border: 1px solid var(--rumahl-ui-color-outline);
  --widget-shadow: none;
  --widget-ink: var(--rumahl-ui-color-text-primary);
  --widget-muted: var(--rumahl-ui-color-text-muted);
  --dock-background: var(--rumahl-ui-color-panel-background);
  --dock-surface: var(--rumahl-ui-color-panel-background);
  --dock-surface-border: 1px solid var(--rumahl-ui-color-outline);
  --dock-surface-shadow: none;
  --dock-sheen: none;
  --label-ink: var(--rumahl-ui-color-text-primary);
  --glass-solid-background: var(--rumahl-ui-color-panel-background);
  --adaptive-color-duration: 0ms;
  --control-fill: var(--rumahl-ui-color-surface);
  --control-border: var(--rumahl-ui-color-outline);
  --motion-easing-standard: cubic-bezier(0.22, 1, 0.36, 1);
}
.shell {
  background: var(--rumahl-ui-color-canvas-background);
  color: var(--rumahl-ui-color-text-primary);
  letter-spacing: 0.01em;
}
.shell .wallpaper {
  background: var(--rumahl-ui-texture-wallpaper);
}

/* Floating chrome: opaque ink panels with a brass hairline. */
.shell[data-material="solid"] .topbar__island.topbar__island {
  background: var(--rumahl-ui-color-panel-background);
  border: 1px solid var(--rumahl-ui-color-outline);
  border-radius: 2px;
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--rumahl-ui-color-accent) 34%, transparent);
}
.shell .shell-window {
  background: var(--rumahl-ui-color-surface-strong);
  border: 1px solid var(--rumahl-ui-color-outline);
  border-radius: 3px;
  box-shadow: 0 30px 80px rgb(0 0 0 / 0.55);
}
.shell .shell-window__titlebar {
  background: var(--rumahl-ui-color-panel-background);
  border-bottom: 1px solid var(--rumahl-ui-color-outline);
  color: var(--rumahl-ui-color-text-primary);
}
.shell .shell-window__titlebar p {
  color: var(--rumahl-ui-color-accent);
  letter-spacing: 0.18em;
  text-transform: uppercase;
}
.shell .shell-window__titlebar h2 {
  font-family: var(--rumahl-ui-typography-display);
  font-weight: 500;
  letter-spacing: 0.01em;
}
.shell .shell-window__controls button {
  border-radius: 2px;
  background: color-mix(in srgb, var(--rumahl-ui-color-text-primary) 7%, transparent);
}
.shell .shell-window__controls button:hover {
  background: color-mix(in srgb, var(--rumahl-ui-color-accent) 24%, transparent);
}

/* Classic taskbar: ink bar, brass controls, compact labelled buttons. */
.shell .taskbar {
  background: var(--rumahl-ui-color-panel-background);
  color: var(--rumahl-ui-color-text-primary);
  border-top: 1px solid var(--rumahl-ui-color-outline);
  box-shadow: 0 -18px 44px rgb(0 0 0 / 0.4);
  min-height: 42px;
  padding: 4px 8px;
  gap: 4px;
  letter-spacing: 0.04em;
}
.shell .taskbar__start {
  width: 34px;
  background: var(--rumahl-ui-color-accent);
  color: var(--rumahl-ui-color-on-accent);
  border: 0;
  border-radius: 2px;
}
.shell .taskbar__start:hover {
  background: var(--rumahl-ui-color-accent-strong);
}
.shell .taskbar__start svg {
  width: 16px;
  height: 16px;
}
.shell .taskbar__button {
  height: 28px;
  max-width: 168px;
  padding: 0 8px;
  gap: 6px;
  background: transparent;
  border: 1px solid transparent;
  border-radius: 2px;
  color: var(--rumahl-ui-color-text-primary);
  font-size: 12px;
  line-height: 1;
}
.shell .taskbar__button > span:first-child:not(:last-child) {
  width: 16px;
  height: 16px;
  border-radius: 2px;
}
.shell .taskbar__button:hover,
.shell .taskbar__button[aria-pressed="true"],
.shell .taskbar__button[data-focused="true"] {
  background: color-mix(in srgb, var(--rumahl-ui-color-accent) 16%, transparent);
  border-color: color-mix(in srgb, var(--rumahl-ui-color-accent) 34%, transparent);
}
.shell .taskbar__windows,
.shell .taskbar__tray {
  border-left-color: var(--rumahl-ui-color-outline);
}
.shell .taskbar__clock {
  padding: 0 7px;
  color: var(--rumahl-ui-color-accent);
  font-size: 11.5px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

/* Desktop */
.shell .desktop-icon__label {
  padding: 1px 4px;
  border: 1px solid color-mix(in srgb, var(--rumahl-ui-color-outline) 82%, transparent);
  border-radius: 2px;
  background: color-mix(in srgb, var(--rumahl-ui-color-panel-background) 86%, transparent);
  text-shadow: none;
}
.shell .desktop-icon.is-selected {
  background: color-mix(in srgb, var(--rumahl-ui-color-accent) 14%, transparent);
  border-color: color-mix(in srgb, var(--rumahl-ui-color-accent) 42%, transparent);
}

/* Settings, files, store share the same ink card language. */
.shell :is(.settings-group, .rumahl-group) {
  background: var(--rumahl-ui-color-surface);
  border: 1px solid var(--rumahl-ui-color-outline);
  border-radius: 3px;
  box-shadow: none;
}
.shell :is(.section-title, .settings-section-title, .settings-content .section-title) {
  font-family: var(--rumahl-ui-typography-display);
  font-weight: 500;
  color: var(--rumahl-ui-color-accent);
  letter-spacing: 0.04em;
  text-transform: none;
}
.shell .files-app__sidebar {
  background: var(--rumahl-ui-color-panel-background);
  border-right: 1px solid var(--rumahl-ui-color-outline);
}
.shell :is(.files-nav, .settings-nav__row) {
  border-radius: 2px;
}
.shell :is(.files-nav.is-active, .settings-nav__row.is-active, .settings-sidebar a[aria-current="page"]) {
  background: color-mix(in srgb, var(--rumahl-ui-color-accent) 15%, transparent);
  color: var(--rumahl-ui-color-text-primary);
  box-shadow: inset 2px 0 0 var(--rumahl-ui-color-accent);
}
.shell :is(.store-grid-card, .store-card, .store-edit-card, .store-product-hero) {
  background: var(--rumahl-ui-color-surface);
  border: 1px solid var(--rumahl-ui-color-outline);
  border-radius: 3px;
  box-shadow: none;
}
.shell :is(.store-grid-card__media, .store-shot, .store-art, .store-cover, .store-icon) {
  border-radius: 2px;
}
.shell .btn {
  border-radius: 2px;
}
.shell .btn.btn--primary {
  background: var(--rumahl-ui-color-accent);
  border-color: var(--rumahl-ui-color-accent);
  color: var(--rumahl-ui-color-on-accent);
}
.shell .btn.btn--primary:hover {
  background: var(--rumahl-ui-color-accent-strong);
  border-color: var(--rumahl-ui-color-accent-strong);
}
.shell :focus-visible {
  outline: 2px solid var(--rumahl-ui-color-accent);
  outline-offset: 2px;
}
.shell ::selection {
  background: color-mix(in srgb, var(--rumahl-ui-color-accent) 30%, transparent);
  color: var(--rumahl-ui-color-text-primary);
}
